# Build the expected output by filling each color's bounding box
input_grid = [
    [5, 0, 5, 0, 0, 5],
    [0, 5, 0, 0, 0, 5],
    [5, 5, 5, 0, 0, 0],
    [0, 0, 0, 4, 0, 4],
    [0, 0, 0, 0, 0, 0],
    [4, 0, 0, 4, 0, 0],
    [2, 0, 2, 0, 2, 2],
    [2, 2, 0, 2, 2, 2],
    [2, 2, 2, 2, 2, 2],
    [0, 0, 8, 8, 0, 0],
    [0, 8, 0, 0, 8, 8],
    [0, 0, 0, 8, 0, 0]
]

def find_color_regions(grid):
    """Find bounding boxes for each non-zero color"""
    regions = {}
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != 0 and val not in regions:
                regions[val] = {'min_r': r, 'max_r': r, 'min_c': c, 'max_c': c}
            elif val != 0:
                if r < regions[val]['max_r']:
                    pass  # Already processed
            if val != 0:
                regions[val]['max_r'] = max(regions[val]['max_r'], r)
                regions[val]['max_c'] = max(regions[val]['max_c'], c)

    # Recalculate properly
    regions = {}
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != 0:
                if val not in regions:
                    regions[val] = []
                regions[val].append((r, c))

    result = {}
    for color, cells in regions.items():
        rows = [c[0] for c in cells]
        cols = [c[1] for c in cells]
        result[color] = (min(rows), max(rows), min(cols), max(cols))
    return result

regions = find_color_regions(input_grid)
print("Color regions:", regions)

# Build output grid by filling each region
output = [[0]*6 for _ in range(12)]

for color, bbox in regions.items():
    min_r, max_r, min_c, max_c = bbox
    print(f"Filling color {color} from ({min_r},{min_c}) to ({max_r},{max_c})")
    for r in range(min_r, max_r+1):
        for c in range(min_c, max_c+1):
            output[r][c] = color

print("\nOutput grid:")
for row in output:
    print(row)

